"use client";

import { useMemo, useState, useTransition } from "react";
import { Popover as PopoverPrimitive } from "radix-ui";

export type ReferenceOption = { id: string; name: string };
export type PickedReference = { id: string; name: string; splitPercent?: number };

/**
 * Reused for the Song form's Writers, Labels, and Artists sections.
 *
 * Search is client-side over the reference list passed in via `options` —
 * catalog-admin lists are small enough that this meets PRD §5's "fast,
 * forgiving search" without a dedicated search endpoint. If the catalog
 * grows enough that this list becomes unwieldy, swap the filter for a
 * server-side search call without changing this component's shape.
 *
 * Phase 2 note: "Add "<name>"" is a simplified stand-in for the PRD's
 * writer-add *dialog* (§3 point 3) — it creates and selects inline without
 * a separate modal. Functionally equivalent (create, refresh, auto-select),
 * but worth revisiting as a real dialog in a later polish pass.
 */
export function MultiReferencePicker({
  label,
  options,
  initialSelected,
  withSplit = false,
  createAction,
  hiddenFieldName,
}: {
  label: string;
  options: ReferenceOption[];
  initialSelected: PickedReference[];
  withSplit?: boolean;
  createAction: (name: string) => Promise<{ id: string; name: string }>;
  hiddenFieldName: string;
}) {
  const [allOptions, setAllOptions] = useState(options);
  const [selected, setSelected] = useState<PickedReference[]>(initialSelected);
  const [query, setQuery] = useState("");
  const [isPending, startTransition] = useTransition();

  const selectedIds = useMemo(() => new Set(selected.map((s) => s.id)), [selected]);

  const matches = useMemo(() => {
    const q = query.trim().toLowerCase();
    if (!q) return [];
    return allOptions
      .filter((o) => !selectedIds.has(o.id) && o.name.toLowerCase().includes(q))
      .slice(0, 8);
  }, [allOptions, query, selectedIds]);

  const exactMatch = allOptions.some(
    (o) => o.name.toLowerCase() === query.trim().toLowerCase(),
  );

  function addExisting(option: ReferenceOption) {
    setSelected((prev) => [
      ...prev,
      { id: option.id, name: option.name, splitPercent: withSplit ? 0 : undefined },
    ]);
    setQuery("");
  }

  function addNew() {
    const name = query.trim();
    if (!name) return;
    startTransition(async () => {
      const created = await createAction(name);
      setAllOptions((prev) => [...prev, created]);
      setSelected((prev) => [
        ...prev,
        { id: created.id, name: created.name, splitPercent: withSplit ? 0 : undefined },
      ]);
      setQuery("");
    });
  }

  function remove(id: string) {
    setSelected((prev) => prev.filter((s) => s.id !== id));
  }

  function updateSplit(id: string, value: number) {
    setSelected((prev) =>
      prev.map((s) => (s.id === id ? { ...s, splitPercent: value } : s)),
    );
  }

  const totalSplit = withSplit
    ? selected.reduce((sum, s) => sum + (s.splitPercent ?? 0), 0)
    : null;

  const isOpen = query.trim().length > 0;

  return (
    <div>
      <PopoverPrimitive.Root open={isOpen} onOpenChange={(next) => !next && setQuery("")}>
        <PopoverPrimitive.Anchor asChild>
          <input
            type="text"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            placeholder={`Search or add a ${label.toLowerCase().replace(/s$/, "")}…`}
            className="w-full rounded-[var(--radius-control)] border border-console-border bg-console-bg px-3 py-2 text-sm text-console-text placeholder:text-console-text-muted focus:border-console-accent"
          />
        </PopoverPrimitive.Anchor>
        <PopoverPrimitive.Portal>
          <PopoverPrimitive.Content
            align="start"
            sideOffset={4}
            onOpenAutoFocus={(e) => e.preventDefault()}
            className="z-10 w-72 rounded-[var(--radius-control)] border border-console-border bg-console-panel shadow-lg"
          >
            {matches.map((option) => (
              <button
                key={option.id}
                type="button"
                onClick={() => addExisting(option)}
                className="block w-full truncate px-3 py-2 text-left text-sm hover:bg-console-accent hover:text-console-bg"
                title={option.name}
              >
                {option.name}
              </button>
            ))}
            {!exactMatch && (
              <button
                type="button"
                onClick={addNew}
                disabled={isPending}
                className="block w-full px-3 py-2 text-left text-sm text-console-accent hover:bg-console-border/60 disabled:opacity-50"
              >
                {isPending ? "Adding…" : `Add "${query.trim()}"`}
              </button>
            )}
            {matches.length === 0 && exactMatch && (
              <p className="px-3 py-2 text-sm text-console-text-muted">
                Already added.
              </p>
            )}
          </PopoverPrimitive.Content>
        </PopoverPrimitive.Portal>
      </PopoverPrimitive.Root>

      {selected.length > 0 && (
        <ul className="mt-3 space-y-1.5">
          {selected.map((item) => (
            <li
              key={item.id}
              className="flex items-center gap-3 rounded-[var(--radius-control)] border border-console-border px-3 py-1.5"
            >
              <span className="min-w-0 flex-1 truncate text-sm" title={item.name}>
                {item.name}
              </span>
              {withSplit && (
                <span className="flex items-center gap-1 font-mono text-xs text-console-text-muted">
                  <input
                    type="number"
                    min={0}
                    step="0.01"
                    value={item.splitPercent ?? 0}
                    onChange={(e) => updateSplit(item.id, Number(e.target.value))}
                    className="w-16 rounded-[var(--radius-control)] border border-console-border bg-console-bg px-2 py-1 text-right"
                  />
                  %
                </span>
              )}
              <button
                type="button"
                onClick={() => remove(item.id)}
                className="text-console-text-muted hover:text-console-warn"
                aria-label={`Remove ${item.name}`}
              >
                ×
              </button>
            </li>
          ))}
        </ul>
      )}

      {withSplit && selected.length > 0 && totalSplit !== 100 && (
        <p className="mt-2 text-xs text-console-warn">
          Splits total {totalSplit}% — PRD allows this, but it&apos;s flagged for
          review before the total should be treated as final.
        </p>
      )}

      <input type="hidden" name={hiddenFieldName} value={JSON.stringify(selected)} />
    </div>
  );
}
